export const COLOR_ROLES=[['background','Fondo'],['accent','Acento'],['text','Texto principal'],['muted','Texto secundario'],['positive','Favorable'],['negative','Desfavorable'],['warning','Alerta'],['borderColor','Borde']];
export function hexToHSV(hex){const [r,g,b]=hex.match(/[a-f\d]{2}/ig).map(x=>parseInt(x,16)/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;let h=0;if(d)h=(max===r?(g-b)/d+(g<b?6:0):max===g?(b-r)/d+2:(r-g)/d+4)*60;return {h,s:max===0?0:d/max,v:max};}
export function hsvToHex(h,s,v){h=((h%360)+360)%360;s=Math.min(1,Math.max(0,s));v=Math.min(1,Math.max(0,v));const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;const a=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return '#'+a.map(n=>Math.round((n+m)*255).toString(16).padStart(2,'0')).join('');}
export function contrastRatio(a,b){const lum=h=>{const rgb=h.match(/[a-f\d]{2}/ig).map(n=>{const v=parseInt(n,16)/255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4;});return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722;};const x=lum(a),y=lum(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
export function paletteFrom(c){return Object.fromEntries(COLOR_ROLES.map(([key])=>[key,c[key]]));}
export function sanitizePalette(raw){if(!raw||typeof raw!=='object')return null;const result={};for(const [key]of COLOR_ROLES){if(!/^#[0-9a-f]{6}$/i.test(raw[key]))return null;result[key]=raw[key].toLowerCase();}return result;}
